class Solution:
    def maxTotalValue(self, nums: List[int], k: int) -> int:
        n = len(nums)

        lg = [0] * (n + 1)
        for i in range(2, n + 1):
            lg[i] = lg[i // 2] + 1

        K = lg[n] + 1

        mx = [[0] * n for _ in range(K)]

        mn = [[0] * n for _ in range(K)]

        for i in range(n):
            mx[0][i] = nums[i]
            mn[0][i] = nums[i]

        for j in range(1, K):
            length = 1 << j

            for i in range(n - length + 1):
                mx[j][i] = max(
                    mx[j - 1][i],
                    mx[j - 1][i + (length >> 1)]
                )

                mn[j][i] = min(
                    mn[j - 1][i],
                    mn[j - 1][i + (length >> 1)]
                )

        def get_value(l, r):
            length = r - l + 1
            p = lg[length]

            mx_val = max(
                mx[p][l],
                mx[p][r - (1 << p) + 1]
            )

            mn_val = min(
                mn[p][l],
                mn[p][r - (1 << p) + 1]
            )

            return mx_val - mn_val

        import heapq

        pq = []

        for l in range(n):
            heapq.heappush(
                pq,
                (-get_value(l, n - 1), l, n - 1)
            )

        ans = 0

        for _ in range(k):
            neg_val, l, r = heapq.heappop(pq)

            val = -neg_val
            ans += val

            if r > l:
                heapq.heappush(
                    pq,
                    (-get_value(l, r - 1), l, r - 1)
                )

        return ans

class Solution:
    def assignEdgeWeights(self, edges: List[List[int]]) -> int:
        mod = 1_000_000_007
        n = len(edges) + 1
        graph = [[] for _ in range(n + 1)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        def dfs(node: int, prev: int) -> int:
            d = 0
            for c in graph[node]:
                if c != prev:
                    d = max(d, dfs(c, node) + 1)
            return d

        return pow(2, dfs(1, 0) - 1, mod)

